const KEY_AT = (...pts) => [...new Set(pts.map(([x, y]) => { for (const n of Object.keys(E).reverse()) { const [x0, y0, g] = E[n], r = g.split("\n")[1 + y - y0]; const ch = r && [...r][x - x0]; if (ch && ch !== ".") return ch } return "" }))].join("")
